const j=$input.first().json;
for(const k of ['product_name','product_image','supplier_url','verified_features']) if(!j[k]) throw new Error(k+' required');
if(!Array.isArray(j.verified_features)||!j.verified_features.length) throw new Error('verified_features must be a non-empty list');
const variations=Math.min(5,Math.max(1,Number(j.variant_count)||1));
return [{json:{product_id:String(j.product_id||'product-'+Date.now()),product_name:j.product_name,asset_source:j.product_image,supplier_url:j.supplier_url,verified_features:j.verified_features,copy_drafts:Array.from({length:variations},(_,i)=>({variant:i+1,headline_status:'draft_required',description_status:'draft_required'})),review_content:'Use only verified customer reviews supplied with permission; none are synthesized.',claims_review:'pending proof',store_adapter:'PENDING: no verified platform API selected',publish_status:'disabled'}}];
